$path = "HKCU:\Software\Microsoft\GameBar" try { $value = Get-ItemPropertyValue -Path $path -Name "AutoGameModeEnabled" -ErrorAction Stop if ($value -eq 1) { Write-Host "Windows Game Mode ist aktiviert." -ForegroundColor Green } else { Write-Host "Windows Game Mode ist deaktiviert." -ForegroundColor Yellow } } catch { Write-Host "Game-Mode-Einstellung konnte nicht gelesen werden." -ForegroundColor Red } Read-Host "Drücke Enter zum Beenden"
